import{_ as e,c as a,o as s,a4 as t}from"./chunks/framework.ttppV29E.js";const m=JSON.parse('{"title":"Finding Controls by Name or ID","description":"","frontmatter":{},"headers":[],"relativePath":"docs/advanced-topics/finding-controls-by-name-or-id.md","filePath":"docs/advanced-topics/finding-controls-by-name-or-id.md","lastUpdated":1787222178000}'),i={name:"docs/advanced-topics/finding-controls-by-name-or-id.md"},n=t(`<h1 id="finding-controls-by-name-or-id" tabindex="-1">Finding Controls by Name or ID <a class="header-anchor" href="#finding-controls-by-name-or-id" aria-label="Permalink to &quot;Finding Controls by Name or ID&quot;">​</a></h1><p>When a step refers to a form field, an AireFrame subject field, a table filter, or a table action, you give AireAssert a plain piece of text - usually whatever the on-screen label says. Every control also has an ID (sometimes called a &quot;Key&quot;) set up behind the scenes when the form or screen was built. AireAssert lets you refer to either one, and this page explains exactly how it decides which you meant.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to &quot;The rule&quot;">​</a></h2><ul><li>If your reference <strong>starts with <code>#</code></strong>, AireAssert treats it as an ID and only an ID. It will not fall back to matching a label.</li><li>Otherwise, AireAssert <strong>tries the ID first</strong>. If nothing matches, it then tries matching the on-screen label instead.</li></ul><p>In practice this means you can almost always just type the label you see on screen, and it will work. The <code>#</code> prefix is there for the times you need to be explicit - most commonly when a label happens to look exactly like another control&#39;s ID, or when you want a step to keep working even if someone later changes the wording of a label.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-gherkin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gherkin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Matches the control labelled &quot;Date of birth&quot; on screen</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">When </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">we set </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Date of birth&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;01/01/1990&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Matches the control with the ID &#39;dateOfBirth&#39;, regardless of what its label currently says</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">When </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">we set </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#dateOfBirth&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;01/01/1990&#39;</span></span></code></pre></div><h2 id="where-this-applies" tabindex="-1">Where this applies <a class="header-anchor" href="#where-this-applies" aria-label="Permalink to &quot;Where this applies&quot;">​</a></h2><p>This convention is used consistently wherever AireAssert asks you to name a control:</p><ul><li>AireForms controls, referred to by their on-screen label or their control ID.</li><li>AireFrame subject fields, when creating, updating or asserting against a subject.</li><li>AireFrame table widget filters.</li><li>AireFrame table actions, and the input fields those actions need.</li><li>AireFrame dashboards, when selecting one to view.</li><li>AireFrame locations and departments (see AireFrame&#39;s own Configuration &gt; Structure Configuration screen for the Key and Display Name of each)</li></ul>`,10),r=[n];function o(l,h,c,d,p,u){return s(),a("div",null,r)}const g=e(i,[["render",o]]);export{m as __pageData,g as default};
